import Badge from "../../../components/ui/Badge.jsx";
import useMarketStatus from "../useMarketStatus.js";
import { formatDateTime } from "../../../utils/date.utils.js";
import "./MarketStatusBadge.css";

// Two honest labels for pages that show stock prices: whether the market is open, and that the prices are SIMULATED
// (generated by TradeOS, not taken from an exchange). Shows nothing until the status has loaded.
export default function MarketStatusBadge({ className = "" }) {
  const { status } = useMarketStatus();

  if (!status) return null;

  const closedHint = status.nextOpenAt
    ? `${status.holidayName ? `${status.holidayName}. ` : ""}Opens ${formatDateTime(status.nextOpenAt)}`
    : "Market closed";

  return (
    <span className={`market-status-badge ${className}`.trim()}>
      <span title={status.isOpen ? "Prices are moving" : closedHint}>
        <Badge variant={status.isOpen ? "success" : "warning"}>
          {status.isOpen ? "Market open" : "Market closed"}
        </Badge>
      </span>

      {status.priceSource === "simulated" && (
        <span title="Stock prices are simulated by TradeOS. They are not real exchange prices.">
          <Badge variant="neutral">Simulated</Badge>
        </span>
      )}
    </span>
  );
}
